  win()   { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => tone(f, 0.18, 'square', 0.2), i * 110)); },
  lose()  { [392, 330, 262, 196].forEach((f, i) => setTimeout(() => tone(f, 0.25, 'sawtooth', 0.18), i * 160)); },
  tick()  { tone(880, 0.04, 'square', 0.06); },
};

