let balloons = [], arrows = [], parts = [], texts = [];
let score = 0, popped = 0, shots = 0, timeLeft = SHOT_TIME;
let mouse = { x: W * 0.6, y: H * 0.4 };
let draw = 0;          // 0..1 bow pull
let lastTick = -1;
let shake = 0;
let t = 0;

const BALLOON_COLORS = ['#e04040', '#40a0e0', '#50c050', '#e0a030', '#b060d0', '#e060a0'];

function rnd(a, b) { return a + Math.random() * (b - a); }

function spawnBalloon() {
  const big = Math.random() < 0.25;
  balloons.push({
    x: rnd(320, W - 60),
    y: GROUND + 40,
    vy: -rnd(26, big ? 40 : 55),
    r: big ? rnd(30, 36) : rnd(20, 27),
    color: BALLOON_COLORS[(Math.random() * BALLOON_COLORS.length) | 0],
    sway: rnd(0, Math.PI * 2),
    swayAmp: rnd(10, 26),
    swaySpd: rnd(0.8, 1.6),
    big,
  });
}

